#!/usr/bin/env python3
"""只给固定上游commit应用受控iOS候选补丁；此工具不授予离线发布资格。"""
import argparse
import difflib
import hashlib
import importlib.util
import json
import pathlib
import subprocess

TAG = 'libreoffice-26.2.6.3'
COMMIT = '8221e31b3ac356a1623c672912a3d2b492f7e3d1'
ROOT = pathlib.Path(__file__).resolve().parent
RECEIPT = '.office-pdf-offline-policy.json'


def digest(value):
    return hashlib.sha256(value).hexdigest()


def git(source, *args):
    return subprocess.check_output(['git', '-C', str(source), *args])


def load_policy():
    raw = (ROOT / 'offline-policy.json').read_bytes()
    policy = json.loads(raw)
    if policy['schema'] != 1 or policy['policyId'] != 'lizhao-office-pdf-ios-offline-candidate-v1' or \
            (policy['sourceTag'], policy['sourceCommit'], policy['qualified']) != (TAG, COMMIT, False):
        raise ValueError('候选策略身份或资格状态不匹配')
    paths = [entry['path'] for entry in policy['files']]
    if not paths or len(paths) != len(set(paths)):
        raise ValueError('策略文件清单为空或重复')
    policy['policySha256'] = digest(raw)
    return policy


def transform(original, entry):
    if digest(original) != entry['beforeSha256']:
        raise ValueError('上游文件SHA-256漂移: ' + entry['path'])
    value = original.decode('utf-8')
    for replacement in entry['replacements']:
        before = replacement['before']
        if not before or value.count(before) != 1:
            raise ValueError('补丁锚点不唯一: ' + entry['path'])
        value = value.replace(before, replacement['after'], 1)
    result = value.encode('utf-8')
    if digest(result) != entry['afterSha256']:
        raise ValueError('补丁结果SHA-256不匹配: ' + entry['path'])
    return result


def expected_receipt(policy):
    return {key: policy[key] for key in ('policyId', 'policySha256', 'sourceTag', 'sourceCommit', 'qualified')}


def prepare_files(source, policy, original_reader):
    """写前校验全部文件，拒绝混合应用、用户改动、符号链接和路径越界。"""
    prepared = []
    states = set()
    for entry in policy['files']:
        relative = pathlib.PurePosixPath(entry['path'])
        if relative.is_absolute() or '..' in relative.parts or '\\' in entry['path']:
            raise ValueError('补丁路径越界')
        target = source.joinpath(*relative.parts)
        if target.is_symlink() or target.resolve() != source.joinpath(*relative.parts):
            raise ValueError('补丁路径含符号链接: ' + entry['path'])
        original = original_reader(entry['path'])
        changed = transform(original, entry)
        current = target.read_bytes()
        if current == original:
            states.add('original')
        elif current == changed:
            states.add('applied')
        else:
            raise ValueError('拒绝覆盖非策略改动: ' + entry['path'])
        prepared.append((target, original, changed))
    if len(states) != 1:
        raise ValueError('补丁部分应用；拒绝自动覆盖或补齐')
    return prepared, states.pop()


def verify_source_identity(source, policy):
    if git(source, 'rev-parse', 'HEAD').decode().strip() != COMMIT:
        raise ValueError('上游HEAD不是固定commit')
    if git(source, 'rev-parse', TAG + '^{commit}').decode().strip() != COMMIT:
        raise ValueError('上游tag不是固定commit')
    if git(source, 'diff', '--cached', '--name-only').strip():
        raise ValueError('上游存在暂存改动；拒绝混入构建')
    changed = set(git(source, 'diff', '--name-only', 'HEAD').decode().splitlines())
    extra = changed - {entry['path'] for entry in policy['files']}
    if extra:
        spec = importlib.util.spec_from_file_location('office_pdf_build_compat', ROOT / 'build_compat.py')
        compatibility = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(compatibility)
        if extra != {entry['path'] for entry in compatibility.patches()}:
            raise ValueError('上游存在策略之外的受跟踪改动')
        # 单独的五文件构建兼容身份；完整清单、精确结果SHA及回执须全部匹配。
        compatibility.verify(source)


def apply_or_verify(source, check=False):
    source = source.resolve(strict=True)
    policy = load_policy()
    verify_source_identity(source, policy)
    prepared, state = prepare_files(source, policy, lambda name: git(source, 'show', 'HEAD:' + name))
    review_patch = []
    for entry, (_, original, changed) in zip(policy['files'], prepared):
        review_patch.extend(difflib.unified_diff(original.decode('utf-8').splitlines(True),
                            changed.decode('utf-8').splitlines(True),
                            fromfile='a/' + entry['path'], tofile='b/' + entry['path']))
    if ''.join(review_patch).encode('utf-8') != (ROOT / 'offline-policy.patch').read_bytes():
        raise ValueError('审阅patch与精确替换策略不一致')
    receipt = source / RECEIPT
    expected = expected_receipt(policy)
    if state == 'applied':
        if receipt.is_symlink() or not receipt.is_file() or json.loads(receipt.read_bytes()) != expected:
            raise ValueError('已修改源码缺少匹配的策略回执')
    elif check:
        raise ValueError('必须先应用候选离线补丁再构建')
    else:
        if receipt.exists() or receipt.is_symlink():
            raise ValueError('原始源码中已有策略回执，拒绝覆盖')
        written = []
        receipt_created = False
        try:
            for target, original, changed in prepared:
                target.write_bytes(changed)
                written.append((target, original))
            with receipt.open('x', encoding='utf-8', newline='\n') as stream:
                receipt_created = True
                json.dump(expected, stream, ensure_ascii=False, indent=2)
                stream.write('\n')
        except OSError:
            # 只撤销本次刚写入的受控文件；不操作其它上游内容。
            for target, original in reversed(written):
                target.write_bytes(original)
            if receipt_created:
                receipt.unlink(missing_ok=True)
            raise
    return expected


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', required=True, type=pathlib.Path)
    parser.add_argument('--check', action='store_true', help='只核对已应用补丁，不修改源码')
    args = parser.parse_args()
    try:
        result = apply_or_verify(args.source, args.check)
    except (OSError, ValueError, KeyError, subprocess.SubprocessError) as error:
        parser.exit(1, '离线候选策略失败: ' + str(error) + '\n')
    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""仅恢复经过白名单、SHA-256 和路径检查的 Office PDF iOS 文本源码；拒绝覆盖。"""
import argparse
import hashlib
import json
import pathlib
import sys

FORMAT = 'office-pdf-ios-source-v1'
SOURCE_ROOT = 'native-kernels/lizhao-office-pdf-ios'
MAX_FILE_BYTES = 4 * 1024 * 1024
MAX_MANIFEST_BYTES = 28 * 1024 * 1024
# 精确白名单，不能从上传的 manifest 扩大。无文档样本、证书、凭据或其他插件。
ALLOWED_PATHS = (
    'apply_offline_policy.py', 'build_kernel.py', 'build_compat.py', 'offline-policy.json', 'offline-policy.patch',
    'OFFLINE_POLICY.md', 'README.md',
    'include/module.modulemap', 'include/OfficePdfKernel.h', 'src/OfficePdfKernel.mm',
    'src/OfficePdfRegistration.cxx',
    'ci/office-pdf-ios.yml', 'ci/README.md', 'ci/run.py', 'ci/test_run.py', 'ci/pkg_config.py',
    'ci/package_sources.py', 'ci/restore-source.py', 'ci/test_sources.py',
    'tests/input_fixtures.py', 'tests/input_main.swift', 'tests/input_README.md', 'tests/input_run.py',
    'tests/OfficePdfTaskGateTests.swift', 'tests/test_build_kernel.py', 'tests/test_offline_policy.py', 'tests/test_build_compat.py', 'tests/test_vcl_contract.py',
)


def unique_object(pairs):
    value = {}
    for key, item in pairs:
        if key in value:
            raise ValueError('JSON 字段重复：' + key)
        value[key] = item
    return value


def validate_manifest(raw):
    if len(raw) > MAX_MANIFEST_BYTES:
        raise ValueError('源码清单超过体积上限')
    value = json.loads(raw.decode('utf-8'), object_pairs_hook=unique_object)
    if not isinstance(value, dict) or set(value) != {'format', 'root', 'files'}:
        raise ValueError('源码清单结构无效')
    if value['format'] != FORMAT or value['root'] != SOURCE_ROOT or not isinstance(value['files'], list):
        raise ValueError('源码清单身份无效')
    files = {}
    identities = set()
    for item in value['files']:
        if not isinstance(item, dict) or set(item) != {'path', 'content', 'bytes', 'sha256'}:
            raise ValueError('源码文件字段无效')
        path = item['path']
        if not isinstance(path, str) or path not in ALLOWED_PATHS or '\\' in path or ':' in path or '\x00' in path:
            raise ValueError('非白名单或不安全路径')
        parts = pathlib.PurePosixPath(path)
        if parts.is_absolute() or any(part in ('', '.', '..') for part in parts.parts) or parts.as_posix() != path:
            raise ValueError('不安全相对路径')
        identity = path.casefold()
        if identity in identities:
            raise ValueError('源码路径重复：' + path)
        identities.add(identity)
        if not isinstance(item['content'], str) or type(item['bytes']) is not int:
            raise ValueError('源码内容或长度类型无效')
        content = item['content'].encode('utf-8')
        if len(content) > MAX_FILE_BYTES or len(content) != item['bytes']:
            raise ValueError('源码长度不一致：' + path)
        if item['sha256'] != hashlib.sha256(content).hexdigest():
            raise ValueError('源码 SHA-256 不一致：' + path)
        files[path] = content
    if set(files) != set(ALLOWED_PATHS):
        raise ValueError('源码白名单文件不完整')
    return files


def restore(manifest, destination):
    if manifest.is_symlink():
        raise ValueError('拒绝符号链接清单')
    if manifest.stat().st_size > MAX_MANIFEST_BYTES:
        raise ValueError('源码清单超过体积上限')
    files = validate_manifest(manifest.read_bytes())
    # macOS 的 /var -> /private/var 属于工作根之前的系统别名。
    # 先固定真实工作根，再拒绝根内现有链接；不能把根内链接当系统别名放行。
    destination = destination.resolve(strict=True)
    if not destination.is_dir():
        raise ValueError('恢复目标工作目录必须已存在')
    native = destination / 'native-kernels'
    if native.is_symlink() or (native.exists() and not native.is_dir()):
        raise ValueError('native-kernels 目录不安全')
    target = destination / SOURCE_ROOT
    if target.exists() or target.is_symlink():
        raise ValueError('拒绝覆盖已有内核目录')
    native.mkdir(exist_ok=True)
    target.mkdir()  # 原子占有新目录；已有路径即失败，不覆盖并发创建者。
    for relative, content in sorted(files.items()):
        output = target / relative
        output.parent.mkdir(parents=True, exist_ok=True)
        with output.open('xb') as stream:
            stream.write(content)
    return {'root': SOURCE_ROOT, 'files': len(files), 'sha256Verified': True, 'overwritten': False}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--manifest', type=pathlib.Path, default=pathlib.Path('kernel-source.json'))
    parser.add_argument('--destination', type=pathlib.Path, default=pathlib.Path('.'))
    args = parser.parse_args()
    try:
        print(json.dumps(restore(args.manifest, args.destination), ensure_ascii=False))
    except (OSError, ValueError, UnicodeError) as error:
        parser.exit(1, '恢复失败：' + str(error) + '\n')


if __name__ == '__main__':
    main()

