NSString *fileSHA256(NSString *file) {
    NSInputStream *stream = [NSInputStream inputStreamWithFileAtPath:file];
    [stream open];
    CC_SHA256_CTX digest; CC_SHA256_Init(&digest);
    unsigned char buffer[65536]; NSInteger count;
    while ((count = [stream read:buffer maxLength:sizeof(buffer)]) > 0) CC_SHA256_Update(&digest, buffer, (CC_LONG)count);
    [stream close];
    if (count < 0) return nil;
    unsigned char hash[CC_SHA256_DIGEST_LENGTH]; CC_SHA256_Final(hash, &digest);
    NSMutableString *hex = [NSMutableString stringWithCapacity:64];
    for (unsigned char value : hash) [hex appendFormat:@"%02x", value];
    return hex;
}
