    }
    for (NSString *name in @[@"rc", @"fundamentalrc", @"ICU.dat"]) {
        NSDictionary *stat = [files attributesOfItemAtPath:[root stringByAppendingPathComponent:name] error:nil];
        if (![stat[NSFileType] isEqual:NSFileTypeRegular] || [stat fileSize] == 0) return false;
    }
    NSString *manifestPath = [root stringByAppendingPathComponent:@"OfficePdfKernelManifest.json"];
    NSDictionary *attributes = [files attributesOfItemAtPath:manifestPath error:nil];
    if (!attributes || [attributes fileSize] > 4 * 1024 * 1024) return false;
    NSData *bytes = [NSData dataWithContentsOfFile:manifestPath];
    id manifest = bytes ? [NSJSONSerialization JSONObjectWithData:bytes options:0 error:nil] : nil;
    if (![manifest isKindOfClass:NSDictionary.class] || ![manifest[@"sourceTag"] isEqual:@"libreoffice-26.2.6.3"] ||
        ![manifest[@"sourceCommit"] isEqual:@"8221e31b3ac356a1623c672912a3d2b492f7e3d1"] ||
        ![manifest[@"resources"] isKindOfClass:NSArray.class] || [manifest[@"resources"] count] == 0) return false;
