        strlen(OFFICE_PDF_POLICY_SHA256) != 64 ||
        ![policy[@"policySha256"] isEqual:[NSString stringWithUTF8String:OFFICE_PDF_POLICY_SHA256]]) return false;
    bool foundICU = false;
    for (id item in manifest[@"resources"]) {
        if (![item isKindOfClass:NSDictionary.class]) return false;
        id relative = item[@"path"], size = item[@"bytes"], expected = item[@"sha256"];
        if (![relative isKindOfClass:NSString.class] || [relative hasPrefix:@"/"] ||
            [[relative pathComponents] containsObject:@".."] || ![size isKindOfClass:NSNumber.class] ||
            ![expected isKindOfClass:NSString.class] || [expected length] != 64) return false;
        NSString *file = [root stringByAppendingPathComponent:relative];
        if (![[file stringByResolvingSymlinksInPath] isEqual:[[root stringByResolvingSymlinksInPath] stringByAppendingPathComponent:relative]]) return false;
        NSDictionary *stat = [files attributesOfItemAtPath:file error:nil];
        if (![stat[NSFileType] isEqual:NSFileTypeRegular] || [stat fileSize] != [size unsignedLongLongValue]) return false;
        if (![fileSHA256(file) isEqual:expected]) return false;
