// iOS没有安全的强制中断；
// load/save卡住时调用方必须维持draining占槽，不可在另一线程destroy。
NSDictionary *exportDocument(NSDictionary *request) {
    NSString *input = path(request, @"inputPath"), *output = path(request, @"outputPath");
    NSString *resources = path(request, @"resourcePath"), *profile = path(request, @"profilePath");
    id format = request[@"format"], deadline = request[@"deadlineUptimeMs"];
    if (!input || !output || !resources || !profile ||
        ![format isKindOfClass:NSString.class] ||
        ![@[@"doc", @"docx", @"ppt", @"pptx"] containsObject:format] ||
        ![deadline isKindOfClass:NSNumber.class] || !std::isfinite([deadline doubleValue]) || [deadline doubleValue] <= 0 ||
        [input isEqual:output]) return failure(@"INVALID_ARGUMENT", @"KERNEL_REQUEST_INVALID");
    if (expired(deadline)) return failure(@"TIMEOUT", @"KERNEL_DEADLINE");
    if ([NSFileManager.defaultManager fileExistsAtPath:output]) return failure(@"NATIVE_FAILURE", @"KERNEL_OUTPUT_EXISTS");
    if (!resourcesValid(resources)) return failure(@"ENGINE_UNAVAILABLE", @"KERNEL_RESOURCE_INTEGRITY_FAILED");
    if (![NSFileManager.defaultManager createDirectoryAtPath:profile withIntermediateDirectories:YES attributes:nil error:nil])
        return failure(@"NATIVE_FAILURE", @"KERNEL_PROFILE_CREATE_FAILED");
    if (expired(deadline)) return failure(@"TIMEOUT", @"KERNEL_DEADLINE");
    // profile是插件长期独立目录，不属于任务临时目录；LO资源/profile首次初始化后固定。
    NSURL *inputURL = [NSURL fileURLWithPath:input], *outputURL = [NSURL fileURLWithPath:output];
    NSURL *profileURL = [NSURL fileURLWithPath:profile isDirectory:YES];
    const std::string resourceIdentity(resources.fileSystemRepresentation);
    const std::string profileIdentity(profileURL.absoluteString.UTF8String);
    if (engineState.attempted && (engineState.resources != resourceIdentity || engineState.profile != profileIdentity))
        return failure(@"ENGINE_UNAVAILABLE", @"KERNEL_PROCESS_IDENTITY_CHANGED");
    if (!engineState.attempted) {
        engineState.attempted = true;
        engineState.resources = resourceIdentity;
        engineState.profile = profileIdentity;
        engineState.office = lok_init_2(resourceIdentity.c_str(), profileIdentity.c_str());
    }
    // 失败后不重试初始化可能部分启动的LO全局状态；需应用进程重启。
    LibreOfficeKit *office = engineState.office;
    if (!office) return failure(@"ENGINE_UNAVAILABLE", @"KERNEL_INIT_FAILED");
    if (!LIBREOFFICEKIT_HAS(office, setDocumentPassword) ||
        !LIBREOFFICEKIT_HAS(office, documentLoadWithOptions) ||
        !LIBREOFFICEKIT_HAS(office, registerCallback) ||
        !LIBREOFFICEKIT_HAS(office, setOptionalFeatures)) return failure(@"NATIVE_FAILURE", @"KERNEL_ABI_MISMATCH");
    PasswordState password{office};
    struct CallbackRegistration {
        LibreOfficeKit *office;
        ~CallbackRegistration() { office->pClass->registerCallback(office, nullptr, nullptr); }
    } registration{office};
    office->pClass->registerCallback(office, callback, &password);
    office->pClass->setOptionalFeatures(office, LOK_FEATURE_DOCUMENT_PASSWORD | LOK_FEATURE_DOCUMENT_PASSWORD_TO_MODIFY);
    // 固定tag非Android分支识别EnableMacrosExecution=false并设置NEVER_EXECUTE。
    // 本地候选补丁在Kit加载入口强制NEVER_EXECUTE/NO_UPDATE；尚待Apple与恶意样本验证。
    Document document(office->pClass->documentLoadWithOptions(office, inputURL.absoluteString.UTF8String,
        "EnableMacrosExecution=false,MacroSecurityLevel=3"));
    NSDictionary *result;
    if (password.requested.load()) result = failure(@"PASSWORD_REQUIRED", @"DOCUMENT_PASSWORD_REQUIRED");
    else if (!document) result = failure(@"NATIVE_FAILURE", @"KERNEL_DOCUMENT_LOAD_FAILED");
    else if (expired(deadline)) result = failure(@"TIMEOUT", @"KERNEL_DEADLINE");
    else {
        const int expected = [format hasPrefix:@"doc"] ? LOK_DOCTYPE_TEXT : LOK_DOCTYPE_PRESENTATION;
        if (document->pClass->getDocumentType(document.get()) != expected) result = failure(@"TYPE_MISMATCH", @"FORMAT_CONTENT_MISMATCH");
        else {
            document->pClass->initializeForRendering(document.get(), "{}");
            int saved = document->pClass->saveAs(document.get(), outputURL.absoluteString.UTF8String, "pdf", "");
            if (expired(deadline)) result = failure(@"TIMEOUT", @"KERNEL_DEADLINE");
            else if (!saved) result = failure(@"NATIVE_FAILURE", @"KERNEL_SAVE_FAILED");
            else result = @{ @"type": @"success", @"sourceFormat": format, @"engineVersion": @"26.2.6.3", @"released": @YES };
        }
    }
    // callback上下文在解除注册前必须存活；engine/profile继续驻留进程，不透传客户路径。
    document.reset();
    return result;
}
