static const char *convertRequestJSON(const char *requestJSON, bool acceptanceOnly) {
    @autoreleasepool {
        std::unique_lock<std::mutex> lease(engineMutex, std::try_to_lock);
        if (!lease.owns_lock()) return json(failure(@"BUSY", @"KERNEL_BUSY"));
        if (!requestJSON || strlen(requestJSON) > 65536) return json(failure(@"INVALID_ARGUMENT", @"KERNEL_REQUEST_INVALID"));
        NSData *data = [NSData dataWithBytes:requestJSON length:strlen(requestJSON)];
        id request = [NSJSONSerialization JSONObjectWithData:data options:0 error:nil];
        if (![request isKindOfClass:NSDictionary.class]) return json(failure(@"INVALID_ARGUMENT", @"KERNEL_REQUEST_INVALID"));
        @try {
            NSMutableDictionary *result = [exportDocument(request) mutableCopy];
            result[@"testOnly"] = @(acceptanceOnly);
            return json(result);
        }
        @catch (NSException *exception) { (void)exception; return json(failure(@"NATIVE_FAILURE", @"KERNEL_OBJC_EXCEPTION")); }
    }
}
